        dialog.style.cssText = 'box-sizing:border-box;width:min(680px,calc(100vw - 24px));max-height:calc(100dvh - 24px);overflow:auto;padding:var(--pg-collection-padding,16px);background:var(--pg-collection-background,var(--pg-background,#fff));color:var(--pg-collection-color,var(--pg-color,#56534c));border:var(--pg-collection-border,1px solid var(--pg-border-color,#56534c));border-radius:var(--pg-collection-radius,6px);font-family:var(--pg-font-family,Helvetica,sans-serif);font-size:var(--pg-font-size,14px)';
